package com.yeyamo_mobile.api.gamification_service.application;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.yeyamo_mobile.api.gamification_service.application.badge.BadgeRule;import com.yeyamo_mobile.api.gamification_service.application.port.*;import com.yeyamo_mobile.api.gamification_service.domain.*;
@Service public class GamificationService{private final GamificationRepositoryPort repo;private final GamificationCachePort cache;private final GamificationOutboxPort outbox;private final List<BadgeRule>rules;public GamificationService(GamificationRepositoryPort r,GamificationCachePort c,GamificationOutboxPort o,List<BadgeRule>b){repo=r;cache=c;outbox=o;rules=List.copyOf(b);}@Transactional public void apply(XpActivity activity,String correlation){AwardResult result=repo.award(activity);if(!result.created())return;if(activity.counterType()!=null)repo.incrementCounter(activity.userId(),activity.counterType());outbox.append("gamification.xp.awarded",activity.userId(),correlation,Map.of("userId",activity.userId(),"points",activity.points(),"reason",activity.reason(),"totalXp",result.after().totalXp()));if(activity.destinationId()!=null&&repo.stamp(activity.userId(),activity.destinationId(),activity.eventId()))outbox.append("gamification.passport.stamped",activity.userId(),correlation,Map.of("userId",activity.userId(),"destinationId",activity.destinationId()));if(result.before().level()!=result.after().level()){outbox.append("gamification.level.changed",activity.userId(),correlation,Map.of("userId",activity.userId(),"level",result.after().level()));grantReward(activity.userId(),"LEVEL_"+result.after().level(),"Récompense niveau "+result.after().level(),"level:"+result.after().level(),correlation);}Map<String,Long>counters=repo.counters(activity.userId());for(BadgeRule rule:rules)for(BadgeDefinition badge:rule.evaluate(result.after(),counters))if(repo.grantBadge(activity.userId(),badge,activity.eventId())){outbox.append("gamification.badge.earned",activity.userId(),correlation,Map.of("userId",activity.userId(),"badgeCode",badge.code()));grantReward(activity.userId(),"BADGE_"+badge.code(),"Récompense "+badge.name(),"badge:"+badge.code(),correlation);}cache.evict(activity.userId());}@Transactional(readOnly=true)public GamificationView view(String user){return cache.get(user).orElseGet(()->{var v=new GamificationView(repo.progress(user),repo.badges(user),repo.passport(user),repo.rewards(user));cache.put(user,v);return v;});}@Transactional public Reward claim(String user,UUID id,String correlation){Reward r=repo.claimReward(user,id);outbox.append("gamification.reward.claimed",user,correlation,Map.of("userId",user,"rewardId",id,"rewardCode",r.code()));cache.evict(user);return r;}private void grantReward(String user,String code,String title,String source,String correlation){repo.grantReward(user,code,title,source).ifPresent(r->outbox.append("gamification.reward.granted",user,correlation,Map.of("userId",user,"rewardCode",code,"rewardId",r.id())));}}
